// THE LARGE-theta SERIES. Writing E[psi'(theta + Y)] - psi'(theta) with
// psi'(z) = int_0^inf s e^{-z s}/(1 - e^-s) ds and the generating function
// E[e^{-sY}] = (1 + (mu/theta) w)^(-theta), w = 1 - e^-s, expanding the integrand in s
// (Watson's lemma), and adding mu/(theta c) gives
//   E_tt = sum_{m >= 4} theta^-m sum_{k=2}^{m} C_{m,k} mu^k,
// with exact rational C_{m,k} (the terms of order theta^-1 to theta^-3 cancel in the
// derivation, so no cancellation is left in the evaluation); the first terms are
// -mu^2/(2 theta^4) + (mu^2/2 + mu^3)/theta^5 - .... The table NB2A_C holds C_{m,k} for
// m = 4, ..., 90 in rows of k = 2, ..., m (misure_d34e/agents/negbin2/asym2b.py); the
// entries with k > m - 2 are zero. With x = mu/theta, each term is
// C_{m,k} x^k theta^-(m-k), so the series converges geometrically in x (the ratio
// measured is 1.1 x) and in 1/theta, and no power of mu is formed (mu^90 would overflow).
// The derivatives are termwise,
//   d^a_mu d^b_theta E_tt = sum_{m,k} C_{m,k} k(k-1)...(k-a+1) (-1)^b (m)_b x^(k-a) theta^(-(m-k)-a-b),
// (m)_b = m(m+1)...(m+b-1). The sum over the support loses digits as theta grows (each
// term is of order mu/theta^3 for a result of order mu^2/theta^4); it is kept for
// theta < 60 and for mu/theta > 0.6.
inline bool asym_ok(double mu, double theta) {
    return theta >= 60.0 && mu <= 0.6 * theta;
}

// the number of orders m: the terms fall by 1.1 x per order and by 1.5/theta
inline int asym_orders(double mu, double theta) {
    const double r = std::max(1.1 * mu / theta, 1.5 / theta);
    int mm = 6 + (int) (16.0 / (-std::log10(r)));
    if (mm > 90) mm = 90;
    return mm;
}

// the n-th derivatives: out[b] = d^n E_tt/(d mu^(n-b) d theta^b)
inline void ett_asym(int n, double mu, double theta, double* out) {
    const int mmax = asym_orders(mu, theta);
    const double x = mu / theta, it = 1.0 / theta;
    double xp[92], tp[100];
    xp[0] = 1.0;
    tp[0] = 1.0;
    for (int j = 1; j <= 91; ++j) {
        xp[j] = xp[j - 1] * x;
    }
    for (int j = 1; j < 100; ++j) {
        tp[j] = tp[j - 1] * it;
    }
    for (int b = 0; b <= n; ++b) {
        out[b] = 0.0;
    }
    int off = 0;
    for (int m = 4; m <= mmax; ++m) {
        const double md = (double) m;
        double srm[5];
        double rising = 1.0;
        for (int b = 0; b <= n; ++b) {
            srm[b] = (b % 2 == 0) ? rising : -rising;
            rising *= (md + (double) b);
        }
        for (int k = 2; k <= m; ++k) {
            const double ck = NB2A_C[off + k - 2];
            if (ck != 0.0) {
                const double td = ck * tp[m - k + n];
                const double kd = (double) k;
                double fk = 1.0;
                for (int a = 0; a <= n; ++a) {
                    if (k >= a) {
                        out[n - a] += td * fk * srm[n - a] * xp[k - a];
                    }
                    fk *= (kd - (double) a);
                }
            }
        }
        off += m - 1;
    }
}


// THE LARGE-theta SERIES EXACT IN x = mu/theta. The same Watson expansion as above, taken at fixed
// x instead of in powers of mu: with phi(s) = s + log(1 + x (1 - e^-s)) as the new variable tau,
//   E_tt = sum_{m >= 1} m! theta^-(m+1) beta_m(x),   beta_m = b_m(x) - b_m(0) = P_m(x)/(1 + x)^q_m,
// b_m = [tau^m] f(s(tau)) ds/dtau, f(s) = s/(1 - e^-s); the m = 0 term cancels mu/(theta c). The
// P_m (exact rationals, NB2B_P) and q_m come from a series reversion in sympy (watson.py). The terms
// fall like m/(theta (1 + x)), so nine orders suffice for theta >= 100, and the sum has no
// cancellation for x > 0.6 (the leading orders, which cancel in the series in mu, do not at that x).
// The derivatives are taken through g(x) = beta_m: d^a_mu d^b_theta [theta^-p g(mu/theta)] =
// theta^-(p+a+b) sum_j K_j(x, p) g^(j)(x), the K_j from the recurrence
// d_theta [theta^-q c_j g^(j)] = theta^-(q+1) [(-q c_j - x c_j') g^(j) - x c_j g^(j+1)].
inline bool bser_ok(double mu, double theta) {
    return theta >= 100.0 && mu > 0.6 * theta;
}
